  if (!SOLANA_WALLET_METHODS.has(envelope.request.method)) {
    throw standardErrors.provider.unsupportedMethod(
      `Unsupported Solana method ${envelope.request.method}`
    );
  }
  extractPubkeys(envelope.request);
