export function toEnvelope(
  request: SolanaInvokeRequest,
  chain: string = SOLANA_WALLET_STANDARD_MAINNET
): Envelope {
  const encoded = encodeSolanaRequest(request);
  const envelope: Envelope = {
    chainId: solanaChainId(chain),
    request: encoded,
