export function createCoinbaseWalletSDK(params: CreateProviderOptions) {
  const options: ConstructorOptions = {
    metadata: {
      appName: params.appName || 'App',
      appLogoUrl: params.appLogoUrl || '',
    },
    preference: params.preference ?? {},
  };

  //  ====================================================================
  //  Set the options in the store and rehydrate the store from storage
  //  ====================================================================

  store.config.set(options);

  //  ====================================================================
  //  One-time initialization and validation
  //  ====================================================================

  initializeGlobalOnce();

  // Telemetry is initialized separately so it can be enabled by later SDK instances
  // even if earlier instances had telemetry disabled
  if (options.preference.telemetry !== false) {
    initializeTelemetryOnce();
  }

  validatePreferences(options.preference);

  //  ====================================================================
  //  Return the provider
  //  ====================================================================

  let evmProvider: ProviderInterface | null = null;
  const transport = createTransport(options, store, params.openFn);
  registerSolanaWallet({ transport, session: store.session });

  return {
    connect: async (request?: ConnectOptions): Promise<ConnectResult> => {
      await rehydrationPromise;
      return withMeasurement(
        { surface: 'sdk_connect', method: 'connect', transport },
        (measuredTransport) => connectWallet({ options: request, transport: measuredTransport })
      );
    },
    evm: {
      namespace: 'evm',
      getProvider: () => {
        if (!evmProvider) {
          const injected = getInjectedProvider();
          evmProvider = injected ?? new CoinbaseWalletProvider({ transport, store });
          logProviderSelected({ providerKind: injected ? 'injected' : 'sdk' });
        }

        return evmProvider;
      },
    },
    solana: {
      namespace: 'solana',
      getWallet: () => getRegisteredSolanaWallet(),
    },
  };
}


